function catLabel(c,incoming){return c==='expense'&&incoming?'Hoàn chi tiêu':categories[c]}
function spendNet(out,inn){const n=s=>BigInt(String(s||'0').split('.')[0]);return(n(out)-n(inn)).toString()}
