function compareTx(mode){const abs=t=>{const v=BigInt(t.signed_amount);return v<0n?-v:v},byDate=(a,b)=>b.date.localeCompare(a.date)||b.order-a.order;if(mode==='amount_asc')return(a,b)=>{const x=abs(a),y=abs(b);return x<y?-1:x>y?1:byDate(a,b)};if(mode==='amount_desc')return(a,b)=>{const x=abs(a),y=abs(b);return x<y?1:x>y?-1:byDate(a,b)};return byDate}
