function trxOrderForm(){if(trxNeedCustomer())return;const today=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Ho_Chi_Minh'}).format(new Date()),types=[['','— bỏ trống —'],...Object.entries(trxLineLabels)],row=i=>`<div class="split" style="grid-template-columns:1.3fr 1fr 1fr">${selectField('Dòng '+i+' · loại','type'+i,types,false)}<label class="field">Số lượng<input name="quantity${i}" inputmode="decimal"></label><label class="field">Tiền (USDT)<input name="amount${i}" inputmode="decimal"></label><label class="field">Tên gói (gói tháng)<input name="plan${i}"></label><label class="field">Dịch vụ từ<input name="start${i}" type="date"></label><label class="field">đến<input name="end${i}" type="date"></label></div>`;
modal('Thêm đơn',`${selectField('Khách','customer',view.trx.customers.map(c=>[c.id,c.name]))}${field('Ngày đơn','date','date',today)}${selectField('Điều khoản','mode',[['POSTPAID','Thu sau'],['PREPAID','Thu trước']])}${field('Hạn thu (chỉ khi đã cam kết; để trống nếu không có)','due_date','date','',false)}${field('Căn cứ / bằng chứng của đơn','evidence')}<p class="muted">Nhập số bằng dấu chấm thập phân (ví dụ 12.5). Mỗi dòng bỏ trống loại sẽ bị bỏ qua. Gói tháng ghi mức cấp duy trì ở ô Số lượng.</p>${[1,2,3,4].map(row).join('')}`,f=>{const lines=[1,2,3,4].filter(i=>f.get('type'+i)).map(i=>({type:f.get('type'+i),quantity:numIn(f.get('quantity'+i)),amount_usdt:numIn(f.get('amount'+i)),plan:f.get('plan'+i),service_start:f.get('start'+i),service_end:f.get('end'+i),note:''}));return act('trx-order',{customer:f.get('customer'),date:f.get('date'),terms:{mode:f.get('mode'),due_date:f.get('due_date')||null},evidence:f.get('evidence'),lines})},'Lưu đơn')}
function trxReceiptForm(){if(trxNeedCustomer())return;const today=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Ho_Chi_Minh'}).format(new Date()),incoming=state().transactions.filter(t=>pos(t.signed_amount)&&!t.allocations.some(a=>a.profile));
modal('Ghi khoản thu',`${selectField('Khách','customer',view.trx.customers.map(c=>[c.id,c.name]))}${field('Ngày nhận','date','date',today)}${selectField('Đồng tiền nhận','currency',[['USDT','USDT'],['VND','VND (quy đổi USDT)']])}${field('Số tiền thực nhận','received','text')}${field('Tỷ giá VND/USDT của lần thu này (chỉ khi nhận VND)','rate','text','',false)}${selectField('Gắn giao dịch ngân hàng đã có (chỉ VND, tránh ghi tiền hai lần)','bank_transaction',[['','— không gắn —'],...incoming.map(t=>[t.id,dateText(t.date)+' · '+t.reference+' · '+fmt(t.signed_amount)+' VND'])],false)}${field('Bằng chứng (mã giao dịch / ví / ghi chú)','evidence')}<p class="muted">Khoản thu mới nằm ở “chờ phân bổ”; bấm Phân bổ để cấn vào dòng đơn. Tỷ giá của lần thu không đổi về sau.</p>`,f=>act('trx-receipt',{customer:f.get('customer'),date:f.get('date'),currency:f.get('currency'),received:numIn(f.get('received')),rate:numIn(f.get('rate'))||null,bank_transaction:f.get('bank_transaction')||null,evidence:f.get('evidence')}),'Lưu khoản thu')}
function trxAllocateForm(id){const c=view.trx.customers.find(c=>c.receipts.some(r=>r.id===id)),r=c.receipts.find(r=>r.id===id),lines=c.orders.filter(o=>o.status==='ACTIVE').flatMap(o=>o.lines.filter(l=>pos(l.outstanding)).map(l=>[l.id,`${dateText(o.date)} · ${trxLineLabels[l.type]}${l.plan?' '+l.plan:''} · còn ${usd(l.outstanding)}`]));if(!lines.length){toast('Không còn dòng đơn nào cần thu.',true);return}
const row=i=>`<div class="split" style="grid-template-columns:2fr 1fr">${selectField('Dòng '+i,'line'+i,[['','— bỏ trống —'],...lines],false)}<label class="field">USDT<input name="amount${i}" inputmode="decimal"></label></div>`;
modal('Phân bổ khoản thu · '+c.name,`<p>Còn chờ phân bổ: <strong>${usd(r.unallocated)} USDT</strong>. Bạn chọn dòng nào được trả; hệ thống không tự chọn khoản cũ nhất.</p>${[1,2,3].map(row).join('')}`,f=>{const allocations=[1,2,3].filter(i=>f.get('line'+i)).map(i=>({line:f.get('line'+i),amount_usdt:numIn(f.get('amount'+i))}));if(!allocations.length){toast('Chọn ít nhất một dòng.',true);return false}return act('trx-allocate',{receipt:id,allocations})},'Phân bổ')}
function trxRewardForm(){const today=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Ho_Chi_Minh'}).format(new Date());modal('Ghi thưởng staking',`${field('Ngày nhận thưởng','date','date',today)}${field('Số TRX','trx_amount','text')}${field('Ghi chú (tùy chọn)','note','text','',false)}<p class="muted">Bản đầu chỉ ghi số lượng, không tính giá trị hay lãi/lỗ.</p>`,f=>act('trx-reward',{date:f.get('date'),trx_amount:numIn(f.get('trx_amount')),note:f.get('note')}),'Lưu')}
function trxReportForm(){const last=view.trx.customers.flatMap(c=>c.receipts).filter(r=>r.status==='ACTIVE').map(r=>r.date).sort().at(-1),today=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Ho_Chi_Minh'}).format(new Date());
modal('Báo cáo thực thu TRX / Energy',`${field('Ngày chọn','date','date',last||today)}<label class="field">Kỳ<select name="period"><option value="week">Tuần · thứ Hai–Chủ nhật</option><option value="month" selected>Tháng</option><option value="quarter">Quý</option></select></label><p class="report-note">Chỉ tiền đã nhận theo ngày nhận. Không chia doanh thu theo thời gian dịch vụ, không lãi/lỗ. VND thực nhận hiện riêng; USDT là số đã cấn theo tỷ giá bạn nhập.</p><div id="trx-result"></div>`,async f=>{try{const r=await call('/api/trx-report',Object.fromEntries(f));$('#trx-result').innerHTML=`<h3>${dateText(r.start)} đến trước ${dateText(r.end)}</h3><p>Tổng USDT nhận (đã quy đổi): <strong>${usd(r.received_usdt)}</strong> · nhận trực tiếp USDT: ${usd(r.received_usdt_direct)} · VND thực nhận: <strong>${usd(r.received_vnd)} VND</strong></p><p>Energy một lần: ${usd(r.by_type.ENERGY_ONCE)} · Gói tháng: ${usd(r.by_type.ENERGY_MONTHLY)} · Bán TRX: ${usd(r.by_type.TRX_SALE)} · Chờ phân bổ: ${usd(r.by_type.UNALLOCATED)} (USDT)</p><p>TRX ghi bán theo đơn trong kỳ: ${usd(r.trx_sold)} · Thưởng staking: ${usd(r.trx_rewards)} TRX</p>${r.entries.map(e=>`<div class="source">${esc(dateText(e.date))} · ${esc(trxCustomerName(e.customer))} · ${usd(e.received)} ${e.currency}${e.rate?' @ '+usd(e.rate):''} → ${usd(e.usdt_equivalent)} USDT</div>`).join('')||'<p>Không có khoản thu trong kỳ.</p>'}`;return false}catch(e){toast(e.message,true);return false}},'Xem báo cáo')}
$('#trx').onclick=()=>{if(!view.capabilities?.includes('trx-energy')){toast('Bản chạy chưa hỗ trợ TRX / Energy; khởi động lại backend mới.',true);return}trxMode=true;debtMode=false;render()};
