function catTemplateForm(){const T=catCur().templates||{};modal('Danh mục mẫu',`<p class="muted">Tạo nhanh danh mục theo nghiệp vụ kế toán. Dữ liệu đã phân loại không bị đổi.</p>${Object.entries(T).map(([k,v])=>`<div class="source"><strong>${esc(v.name)}</strong>${v.children.length?'<br><small>Gồm: '+v.children.map(esc).join(', ')+'</small>':''}<br><small>${esc(v.description)}</small><br>${v.exists?'<span class="pill">Đã có</span>':`<button type="button" class="primary" data-tpl="${k}">Tạo danh mục này</button>`}</div>`).join('')}`);
document.querySelectorAll('[data-tpl]').forEach(b=>b.onclick=async()=>{if(await act('category-template',{template:b.dataset.tpl}))$('#dialog').close()})}
const baseRenderCategoriesForTemplate=renderCategories;
